-- Import des courriers arrivées 2012
-- Source : 2012.xlsx (feuille 2012).
-- La colonne CATEGORIES du classeur vaut partout « Demande SERVICES ».
-- txt_categorie est déduite de la désignation, comme en 2014 et 2016.
--
-- Correspondance Excel -> table arrivees
--   N°                      -> txt_numdordre (00001/jj-mm-aaaa) et txt_numcourier
--   DATE CREATION           -> dt_datearrivee et dt_datecourier
--   référence formulaire    -> txt_reference = « <N°> du jj-mm-aaaa »
--   PRENOMS + NOM           -> txt_prenomNom et txt_expediteur
--   DESIGNATIONS            -> txt_objet (libellé d'origine)
--   DESIGNATIONS            -> txt_designation (liste designationsParCategorie)
--   designation retenue     -> txt_categorie
--   N° TF Dakar Gorée       -> txt_numTitreFoncier, ou txt_numTitreMere si un TF Grand Dakar est aussi renseigné
--   N° TF Grand Dakar       -> txt_numTitreFoncier
--   N° LOT                  -> txt_numLot
--   SITUATION               -> txt_lotissement
--   AGENTS TRAITEURS        -> txt_agenttraiteur
--   OBSERVATIONS            -> txt_observation
--
-- txt_typecourrier = BE si la désignation commence par « BE », sinon Individuel
-- txt_nombrepiece = 1
-- N° #VALUE! entre 349 BIS et 351 BIS rétabli en 350 BIS
-- N° vide entre 374 et 376 rétabli en 375
-- Références en doublon : suffixe [n° d'ordre]
-- N° d'arrivée en doublon : suffixe -2, -3…
-- Dates illisibles reconstituées sur la ligne voisine : 3
-- Lignes importées : 1828
--
-- Répartition des catégories :
--    1744  Demande SERVICES
--      61  Information
--      16  Convocation - Invitation
--       5  Réclamation - Signalement
--       2  Réquisition - Instruction
-- Désignations :
--     718  Morcellements
--     373  Autorisation de construction
--     250  Demande de Cession définitive
--     216  Demande de Régularisation par voie de Bail
--      53  Demande de délimitation
--      30  Demande de terrain/Echange
--      23  Litiges
--      23  Duplication de CIC
--      19  Demande d'états des lieux
--      18  Note de service
--      17  Autres
--      13  Réunion
--      12  Autorisation de lotir
--      10  Circulaire
--       6  Demande d'évaluation
--       5  Rapport
--       5  Décision - Arrêté
--       5  Demande de situation foncière
--       5  Plainte
--       5  Réquisition d'immatriculation
--       4  Réceptions de lotissements
--       4  Demande d'extraits de plan
--       3  PV - Compte - rendu
--       2  Demande de Titre foncier
--       2  Instruction à suivre
--       2  Formation
--       1  Transmission lettre
--       1  Atelier
--       1  Lettre
--       1  Tribunal
--       1  Document administratif

SET NAMES utf8mb4;

START TRANSACTION;






COMMIT;
